    aWandererF = 0xBBF1D8F02AE5F0E9ULL;
    aWandererG = 0xAF000B6711111EB6ULL;
    aWandererH = 0xDC8422019AD33D4CULL;
    aWandererI = 0xB45CE667DC21A6D1ULL;
    aWandererJ = 0xAD5E2C2A24CDE3F8ULL;
    aWandererK = 0xDDA5C859F690D940ULL;

    ////////////////////////////////////////////////////////
    //
    // Main twist loops
    //
    TwistExpander_Arcturus_Arx::TWIST_A(PARAMS_TWIST);

    TwistExpander_Arcturus_Arx::TWIST_B(PARAMS_TWIST);

    TwistExpander_Arcturus_Arx::TWIST_C(PARAMS_TWIST);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectB;

    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollA;
